-- Reglement / Firmenordnung (Google Doc 1Ppwjp4gd4tvsCnrRylWoj5O5W-7jTwRuqJRg549hEaE, Version 16.09.2026) als Abschnitte übernehmen.
-- Nur wenn noch keine Abschnitte da sind (Einmal-Übernahme).
insert into doku_abschnitt (vorlage_id, titel, html, sortierung)
select v.id, a.titel, a.html, a.nr
from doku_vorlage v
cross join (values
(1, 'Toms Planner', '<p>Dieses Planungstool dient zur Organisation der Teams und Mitarbeitenden. Unter folgendem Link kann der Mitarbeitende seinen Arbeitseinsatz einsehen. Der Mitarbeitende klärt den Treffpunkt selbständig mit dem Vorarbeiter ab. Kurzfristige Wechsel werden in der Personalplanung vermieden, können aber zum Beispiel infolge von unvorhergesehenen Absenzen von Mitarbeitenden vorkommen. Daher ist es wichtig, den Planer am Vortag (abends) kurz anzuschauen.</p>'),
(2, 'Zeiterfassung', '<p>Jeder Mitarbeitende erfasst täglich seine Arbeitszeit im Timerocket App. Erklärungen zur Zeiterfassung können bei Benu eingeholt werden.</p><p>Beispiel Zeiterfassung Sommer, normaler Arbeitstag:</p><ul><li>07:00 – 09:30</li><li>09:45 – 12:00</li><li>13:00 – 17:15</li></ul>'),
(3, 'Rapporte erfassen', '<p>Der Vorarbeiter oder instruierte Mitarbeiter erfassen täglich den Regierapport für den Kunden. Damit nichts vergessen geht, ist es wichtig, den Rapport am selben Tag zu schreiben.</p>'),
(4, 'Arbeitsstart und Arbeitsschluss', '<p>Grundsätzlich: Innerhalb des Teams entscheidet der Vorarbeiter, bei welchem Sammelplatz die Arbeit startet (Varianten Magazin, Zulgbrücke, direkt auf Baustelle).</p><p><b><i>Arbeitszeit Beispiel Arbeitsstart 07:00</i></b></p><ul><li>4,75 Std. 07:00 bis 12:00 abzüglich Znünipause</li><li>4,25 Std. 13:00 bis 17:15</li><li>9,00 Std. Total Arbeitszeit (Variante Sommerarbeitszeit)</li></ul><p><b><i>Beispiel Arbeitsstart 07:00 im Magazin</i></b></p><p>06:50 Eintreffen 10 Min vor Arbeitsbeginn. Kleider zusammensuchen, WC aufsuchen, Austausch und Schwatz.<br>07:00 Arbeitsstart mit produktiver Arbeit.</p><p><b><i>Beispiel Arbeitsstart 07:00 Grossraum Steffisburg</i></b></p><p>07:00 Abfahrt vom Sammelplatz<br>07:00 Durchfahrt Lauitor Richtung Hilterfingen<br>07:00 Auffahrt auf Autobahn Thun Nord</p><p><b><i>Beispiel Arbeitsstart 07:00 direkt beim Kunden</i></b></p><p>Es ist auch möglich, den Treffpunkt direkt auf die Baustelle zu verlegen: 07:00, wenn die Fahrzeit zur Baustelle gleich oder kürzer als der normale Arbeitsweg ins Magazin ist.</p><p><b>Arbeitsschluss:</b> 17:15, analog oben. Je nach Standort der Baustelle können spezifische Ausnahmeregelungen gemacht werden.</p>'),
(5, 'Mittagspause', '<p>Die Mittagspause beträgt eine Stunde. Das heisst, um 12:00 beim Kunden wegfahren und um 13:00 beim Kunden wieder mit der Arbeit beginnen. Fahrzeiten zum Restaurant oder Einkaufen von Lunch finden in dieser Pausenzeit statt. Die Mittagspause darf nur in Ausnahmefällen verkürzt werden.</p>'),
(6, 'Znünipause', '<p>Die Znünipause beträgt 15 Minuten. Diese Zeit ist <b>nicht bezahlt</b>. In diesen 15 Minuten ist das Einkaufen des Znünis usw. eingerechnet. <b>Das Znüni muss vor dem Arbeitsstart am Morgen eingekauft sein.</b> Das Znüni wird grundsätzlich beim Kunden beziehungsweise auf der Baustelle eingenommen. Wird die Pausenverpflegung ausnahmsweise im Restaurant eingenommen, schreibt der Mitarbeitende für die zusätzliche Zeit entsprechend weniger auf die Stundenkarte ein. Für Znüni in der Firma stehen Tee und Kaffee gratis zur Verfügung.</p>'),
(7, 'Ausflüge / Anlässe', '<p>Laut separatem Programm.</p>'),
(8, 'Auswärtiges Arbeiten mit Übernachtung', '<p>Bei Baustellen, die weiter entfernt sind und daher vor Ort übernachtet werden muss, organisiert der Betrieb eine Übernachtungsmöglichkeit / Hotel. Der Betrieb übernimmt die vollen Übernachtungskosten. Wo keine Halbpension möglich ist, vergütet der Betrieb pro Nachtessen 25.–, pro Morgenessen 10.–.</p><p>Zusätzliche Reisekosten wie Bahnbillett werden vom Betrieb übernommen.</p>'),
(9, 'Weiterbildung', '<p>Bei <b>angeordneter</b> Weiterbildung übernimmt der Betrieb die Kosten der Arbeitszeit, Kurskosten und Reisespesen. Angeordnete Kurse sind:</p><ul><li>Vorgeschriebene Weiterbildungen für Sicherheitsbeauftragte</li><li>Vorgeschriebene Weiterbildungen für Berufsbildner</li><li>Interne Sicherheitskurse von Knecht AG durchgeführt</li></ul><p>Bei durch Knecht AG <b>empfohlenen</b> Kursen übernimmt der Betrieb die Kosten wie folgt:</p><p><b>Für VorarbeiterInnen Gartenpflege, Kurs Obst Fachperson:</b></p><ul><li>Variante 1: 50% der Kurskosten <b>ohne Verpflichtung</b></li><li>Variante 2: 100% von Kurskosten, Arbeitszeit, 100.– Übernachtungspauschale bei Anfahrt länger als 1.5 Std., mit <b>Verpflichtung 2 Jahre</b></li></ul><p><b>Für den Service Spezialisten Wassergarten Aqua Suisse:</b></p><ul><li>Variante 1: 50% der Kurskosten <b>ohne Verpflichtung</b></li><li>Variante 2: 100% von Kurskosten, Arbeitszeit, 100.– Übernachtungspauschale bei Anfahrt länger als 1.5 Std.; 50% der Arbeitszeit übernimmt der Mitarbeitende, 50% bezahlt der Betrieb; mit <b>Verpflichtung 2 Jahre</b></li></ul><p>Der Mitarbeiter kann zwischen den Varianten 1 oder 2 auswählen. Weitere Kurse nach Absprache.</p><p>Bei <b>freiwilligen Kursen</b> kann der Mitarbeitende für branchennahe Weiterbildung freinehmen, zum Beispiel Polier, Bauführer, Meister, Schwimmteichbauer. Eine Beteiligung am Schulgeld ist bei freiwilligen Kursen in Ausnahmefällen möglich.</p>'),
(10, 'Bekleidung / Verbrauchsmaterial', '<p>Die Kleidung muss immer und in sauberem Zustand getragen werden. Die Bekleidung des Grundstockes muss bei einem Austritt in den ersten 12 Monaten gewaschen zurückgegeben werden. Bekleidung wird von der Firma Knecht folgendermassen zur Verfügung gestellt:</p><p><i>Grundstock bei Eintritt:</i></p><ul><li>Hosen können mit 50% Rabatt eingekauft werden</li><li>Total 5 Shirts: T-Shirt, Langarmshirt, Träger-Shirt</li><li>2 Pullover</li><li>1 Winterjacke</li><li>1 Softshell-Jacke</li><li>1 Paar Sicherheitsschuhe</li><li>1 Gehörschutz</li><li>1 Schutzbrille</li><li>1 Doppelmeter</li><li>1 Fuchsschwanz</li><li>1 Felco-Schere</li><li>3 Paar Sommerhandschuhe, nass oder trocken nach Wahl</li><li>2 Paar Winterhandschuhe, nass oder trocken nach Wahl</li><li>Die Firma Knecht bezahlt jedem Mitarbeiter einmalig (beim Eintritt in die Firma) 200.– an die Arbeitsschuhe. Diese müssen bei Beck Bekleidung Oberdiessbach gekauft werden.</li><li>Zusätzliche Kleider können mit 50% Rabatt gekauft werden.</li></ul><p><i>März:</i></p><ul><li><b>3 Paar Shirts nach Wahl kostenlos</b> (Auswahl aus Träger-, Langarm- oder T-Shirt)</li><li><b>1 Pullover kostenlos</b></li><li><b>Hosen mit 50% Rabatt</b></li><li><b>Alle 4 Jahre wahlweise Softshell- oder Winterjacke</b></li><li>Weitere Kleider wie Jacken, Hosen oder zusätzliche Shirts können zu 50% Rabatt gekauft werden.</li></ul><p><i>Während dem Jahr:</i></p><ul><li>Kleider können mit 50% Rabatt gekauft werden.</li><li>Scheren, Meter, Fuchsschwanz, Gehörschutz können zum Einkaufspreis erworben werden.</li></ul><p>Für Kosten der Privatanteile gilt Barzahlung. Die Kleider müssen beschriftet werden. Die Kleider müssen sauber sein.</p>'),
(11, 'Sponsoring von Mitarbeitenden', '<p>Mitarbeitende können für Sponsoring von speziellen Anlässen oder Aktivitäten in ihren Vereinen der Geschäftsleitung eine Anfrage für ein Sponsoring unterbreiten. Die Geschäftsleitung prüft die Anfrage. Wenn ein Beitrag zu einem Sponsoring gutgeheissen wird, beträgt der Maximalbetrag pro Jahr und Mitarbeitenden in der Regel 100.–.</p><p>Beiträge an den jeweiligen Mitarbeitenden werden in der Regel zwischendurch pausiert und nicht jedes Jahr wiederkehrend ausbezahlt.</p>'),
(12, 'Krankheit', '<p>Bei Krankheit gehen die ersten zwei Tage laut GAV zu Lasten des Mitarbeitenden. Ab dem dritten Tag wird der Arbeitstag zu 80% bezahlt. Ab dem dritten Arbeitstag liefert der Mitarbeitende ein Arztzeugnis.</p>'),
(13, 'Unfall', '<p>Bei Unfall wird der Arbeitstag ab erstem Tag zu 80% bezahlt. Der Unfall muss sofort an Benu gemeldet werden. Benu sendet anschliessend per Mail ein Unfallmeldeformular, welches sofort ausgefüllt an Benu zurückgesendet werden muss. Jedes Arztzeugnis auch immer umgehend an Benu senden.</p>'),
(14, 'Arbeitssicherheit', '<p>Der Mitarbeitende verpflichtet sich, jegliche Vorkehrungen zur Arbeitssicherheit umzusetzen, insbesondere das Tragen der persönlichen Schutzausrüstung wie Sicherheitsschuhe, Schutzbrillen usw. Nichteinhalten bedeutet im Wiederholungsfalle die Kündigung.</p>'),
(15, 'Radio auf der Baustelle', '<p>Vor dem Verwenden eines Radios auf der Baustelle muss der Kunde zwingend vorgängig ausdrücklich gefragt werden. Willigt der Kunde ein, darf das Radio in gemässigter Lautstärke verwendet werden, wenn sich der Arbeitsbereich in einem kleinen Gartenteil eingrenzt.</p>'),
(16, 'Gratifikation Lernende', '<p>Bei bestandener Autoprüfung bis am 31.12. des 3. Lehrjahres: 300.– einmalig.</p>'),
(17, 'Lehrlingsakademie / Studienreise', '<p>Die Lehrlingsakademie ist für die Lernenden kostenlos. Die Firma übernimmt die vollen Kosten. Für die Studienreise, welche im 3. Lehrjahr von der Gewerbeschule aus stattfindet, übernehmen die Lernenden die vollen Kosten.</p>'),
(18, 'Spesenregelung', '<ul><li>Mitarbeiter: pauschal 310.– pro Monat bei 100% Anstellung, für Mittagessen, Handybenutzung, Anteil an Arbeitsschuhen und Sonnenschutz</li><li>Lehrlinge: pauschal 200.– pro Monat für Mittagessen, Handybenutzung, Anteil an Arbeitsschuhen und Sonnenschutz</li></ul><p>Bei Absenzen wie Krankheit, Unfall oder Militär werden die Spesen entsprechend gekürzt.</p>'),
(19, 'Mittagessen beim Kunden', '<p>Wenn der Kunde die Mitarbeitenden eine Woche lang bekocht, schenkt der Mitarbeitende dem Kunden einen Pflanzengutschein im Wert von 10.– pro Person pro Tag. Gutscheine können bei der Firma Knecht gekauft werden. Sind es nur 2–3 Mittagessen, freut sich der Kunde nebst dem Merci sicher auch über ein kleines Mitbringsel.</p>'),
(20, 'Entschädigung für private Fahrzeuge', '<p>Voraussetzung zur Entschädigung von privaten Fahrzeugen:</p><ul><li>Vorarbeiter, die den Lieferwagen normalerweise mit nach Hause nehmen, erhalten keine Entschädigung für die private Fahrzeugnutzung.</li><li>Es werden nur die Kilometer, die <b>zusätzlich zum normalen Arbeitsweg</b> anfallen, entschädigt.</li></ul><p>Dem Mitarbeitenden wird die private Fahrzeugnutzung wie folgt entschädigt:</p><ul><li>Motorrad / E-Bike: 5.– pro Tag bei Fahrten nach Thun und Umgebung</li><li>Auto: –.75 pro km</li><li>ÖV: Mehrkosten vom effektiven Ticketpreis</li></ul>'),
(21, 'Fahrzeugbenutzung, Bauführer und Service', '<p>Bauführer dürfen ihre Fahrzeuge in einem normalen Rahmen auch privat nutzen. Für Fahrten, die ausserhalb des Kantons Bern liegen, und für Fahrten an Wochenenden und in den Ferien befüllt der Mitarbeitende den Treibstofftank entsprechend auf seine eigenen Kosten. Die Fahrzeuge sollten nicht von Drittpersonen gelenkt werden.</p>'),
(22, 'Schäden', '<p>Entstehen dem Kunden durch unser Mitwirken Schäden oder Unannehmlichkeiten, geht der Mitarbeitende unverzüglich persönlich mit einem Entschuldigungsstrauss oder dergleichen vorbei. Im Magazin, beim Kunden oder unterwegs entstandene Schäden sind der Geschäftsleitung unverzüglich zu melden.</p><p><b>Schäden an Fahrzeugen und Maschinen und beim Kunden:</b></p><ul><li>Erstmalig einmal pro Jahr übernimmt der Betrieb die gesamte Schadenssumme, der Mitarbeiter bezahlt 50.–</li><li>Der Mitarbeiter übernimmt 50% des Schadens, maximal 500.–</li><li>Bei Schäden durch den Lernenden verursacht übernimmt der Lernende 25% des Schadens, maximal 500.–</li><li>Bei Schäden, die auf der Baustelle entstehen, wird die allfällige Beteiligung des Mitarbeitenden besprochen.</li><li>Bei grob fahrlässig entstandenen Schäden haftet der Mitarbeitende zu 100%.</li><li>Für Schäden, die unter Alkohol- oder Drogeneinfluss entstehen, haftet der Mitarbeitende zu 100%.</li></ul>'),
(23, 'Dienstaltersgeschenk', '<p>Der Mitarbeitende erhält zum 10-jährigen Jubiläum 1000.– Gratifikation.</p>'),
(24, 'Besondere Leistungen', '<ul><li>1. Rang Lehrabschlussprüfung: 5 Gramm Gold</li></ul>'),
(25, 'Rauchen auf der Baustelle', '<p>Rauchen ist auf der Baustelle verboten.</p>'),
(26, 'Spezialkonditionen für Eigenbedarf', '<p>Die Firma Knecht gewährt den Mitarbeitenden Maschinen und Material zu Spezialkonditionen (Pflanzen 30% Rabatt, Maschinen, Material usw. zu Spezialpreisen).</p><p><i>Diese Konditionen gelten unter folgenden Voraussetzungen:</i></p><ul><li>Ausschliesslich für Kleinmengen und den Eigengebrauch, für Arbeiten, welche am Wohnort des Mitarbeitenden ausgeführt werden.</li><li>Grössere Bauprojekte zu Hause müssen im Einzelfall beurteilt werden.</li><li>Jegliche Benutzung von Maschinen, Geräten usw. muss sofort rapportiert werden.</li><li>Wenn nichts anderes abgemacht wurde, gilt Barzahlung.</li><li>Für den Lieferwagen kann der Spezialpreis rapportiert werden.</li></ul>'),
(27, 'Schlüssel', '<p>Für verloren gegangene Schlüssel muss 100.– bezahlt werden.</p>'),
(28, 'Private Lieferwagen-Benutzung', '<p>Pro Kalenderjahr darf jeder Mitarbeitende den Lieferwagen für sich selbst für 100 km kostenlos ausleihen. Jede private Lieferwagen-Benutzung wird ab dem ersten Gebrauch rapportiert und Ende Jahr abgerechnet.</p><p>Wenn der Lieferwagen für Bekannte, Verwandte, Kollegen usw. gebraucht wird, muss der normale Stundensatz des Lieferwagens rapportiert und bezahlt werden.</p>'),
(29, 'Lieferwagen für Fahrt auf Baustelle', '<p>Wenn der Fahrweg zur Baustelle kürzer als ins Magazin/Sammelplatz ist, kann der Lieferwagen zur direkten Fahrt auf die Baustelle verwendet werden. Wenn der Lieferwagen nur zur Fahrt zwischen dem Magazin/Sammelplatz verwendet wird, muss er rapportiert werden (total Verwendung 100 km pro Jahr kostenlos).</p>'),
(30, 'Ferienregelung', '<p>Ferienanträge müssen bis spätestens Dezember des laufenden Jahres für das folgende Jahr eingereicht werden. Die Geschäftsleitung entscheidet über die Genehmigung der Ferienanträge und prüft deren Vereinbarkeit mit der betrieblichen Planung.</p><p>Es dürfen keine Flüge, Hotels, Kurse oder andere verbindliche Buchungen vorgenommen werden, bevor die Ferien nicht offiziell von der Geschäftsleitung genehmigt wurden. Der Betrieb übernimmt keine Kosten für Stornierungen, die durch fehlende Rücksprache bei der Ferienbuchung entstehen.</p><p>Mit Ausnahme der Betriebsferien sind gleichzeitige Ferien mehrerer Mitarbeitender nicht möglich. Bei Überschneidungen von Ferien wird dem zuerst eingereichten Antrag Vorrang gegeben. Ferien im Herbst sind nur möglich, wenn genügend Ferientage oder Überstunden vorhanden sind, um die drei Wochen Betriebsferien im Dezember/Januar abzudecken.</p>'),
(31, 'Betriebsferien', '<ul><li>Eine Woche Betriebsferien letzte Juli-Woche</li><li>Drei Wochen Betriebsferien über Weihnachten/Neujahr (Überzeitabbau)</li></ul>'),
(32, 'Sperrzeit für Ferien', '<p>Im Zeitraum vom 1. März bis zum 31. Mai sind grundsätzlich keine Ferien möglich. Sofern gewisse Punkte berücksichtigt sind, können nach Rücksprache mit der Geschäftsleitung Ferien im Frühling bezogen werden:</p><ul><li>Es können maximal 6 Arbeitstage (inkl. Brückentag nach Auffahrt) bezogen werden.</li><li>Ferien bzw. Freitage müssen bis Mitte Dezember des Vorjahres eingereicht werden.</li><li>Die betriebliche Organisation muss gewährleistet sein: Es müssen genügend komplette Teams verfügbar bleiben.</li><li>Wenn mehrere Mitarbeitende in derselben Woche Ferien wünschen, hat die früheste Anmeldung Vorrang.</li><li>Wer im Frühling Ferien bezieht, zeigt sich im darauffolgenden Winter bei Schlechtwetter flexibel und nimmt – falls nötig – auch mal ein paar Freitage (auch bei Minusstunden).</li></ul>'),
(33, 'Überzeit', '<p>Die Überzeit muss spätestens bis Ende Februar abgebaut werden.</p>'),
(34, 'Lernfahrten mit Lieferwagen / Führen von Lieferwagen im Magazin', '<p>Mit dem Lieferwagen dürfen keine Lernfahrten gemacht werden.</p>'),
(35, 'Führen von Baumaschinen', '<p>Ohne Instruktionskurs dürfen keine grossen Baumaschinen (Bagger, Dumper, Pneulader) bedient werden. Lehrlinge dürfen Bagger usw. nach dem entsprechenden ÜK bedienen. Raupendumper dürfen nach entsprechender Instruktion bedient werden.</p>'),
(36, 'Anhänger', '<p>Mitarbeiter verpflichten sich, innerhalb von 12 Monaten die Anhängerprüfung zu machen. Für Mitarbeiter, die ausschliesslich in der Gartenpflege arbeiten, kann allenfalls eine Ausnahmeregelung gelten.</p>')
) as a(nr, titel, html)
where v.schluessel = 'reglement'
  and not exists (select 1 from doku_abschnitt x where x.vorlage_id = v.id);
